+                    if let (Ok(p), Ok(q)) = (p.parse::<f64>(), q.parse::<f64>()) {
+                        if p != q {
+                            found.push((p, q));
+                        }
+                    }
+                }
+            }
+        }
+        old.clear();
+        new.clear();
+    };
+    for line in hunks.lines() {
+        if line.starts_with("---") || line.starts_with("+++") {
+            continue;
+        }
+        if let Some(rest) = line.strip_prefix('-') {
+            if !new.is_empty() {
+                pair_up(&mut old, &mut new);
+            }
+            old.push(rest);
+        } else if let Some(rest) = line.strip_prefix('+') {
+            new.push(rest);
+        } else {
+            pair_up(&mut old, &mut new);
+        }
+    }
